  let objDescriptor = Object.getOwnPropertyDescriptor(obj, method)
  if (objDescriptor) {
    return objDescriptor
  }
  let currentProto = Object.getPrototypeOf(obj)
  while (currentProto !== null) {
    const descriptor = Object.getOwnPropertyDescriptor(currentProto, method)
    if (descriptor) {
      return descriptor
    }
    currentProto = Object.getPrototypeOf(currentProto)
  }
}

edits.newText:
let getDescriptor = (
  obj: any,
  method: string | symbol | number
): [PropertyDescriptor | undefined, boolean] => {
  let objDescriptor = Object.getOwnPropertyDescriptor(obj, method)
  if (objDescriptor) {
    return [objDescriptor, true]
  }
  let currentProto = Object.getPrototypeOf(obj)
  while (currentProto !== null) {
    const descriptor = Object.getOwnPropertyDescriptor(currentProto, method)
    if (descriptor) {
      return [descriptor, false]
    }
    currentProto = Object.getPrototypeOf(currentProto)
  }
  return [undefined, false]
}

let restore = () => {
    // If the spied method was inherited from the prototype (i.e. not an
    // own property of the instance), `reassign` added an own property to
    // the instance. Deleting that own property restores the original
    // prototype method instead of leaving a leaked own property behind.
    if (!isOwnDescriptor) {
      delete obj[accessName]
      return
    }
    return originalDescriptor && !original
      ? define(obj, accessName, originalDescriptor)
      : reassign(original)
  }

